INSERT INTO "project" ("id", "name", "description", "website_link", "start_date", "is_active", "sort_order") VALUES (
  'tfp', $dqc$Trans Formations Data Archive$dqc$, $dqc$The collective's founders started their queer-advocacy work with another organization, the Trans Formations Project (TFP). TFP focused its efforts on tracking anti-queer legislation efforts across the United States. 9 months into President Donald Trump's second administration, the organization ceased operations in response to growing hositily and concerns for the safety of its members. Upon TFP's disbandment, the founders of DQC assisted with archiving the data and records gathered by TFP. Much of TFP's data can be found here and is welcome to be used for any aligned endeavors.$dqc$,
  'https://transformationsproject.org', 'Spring 2026', true, 0
) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "project_page" ("project_id", "draft_content", "draft_updated_at", "published_content", "published_at") VALUES (
  'tfp', $dqc${"root":{"type":"root","children":[{"type":"heading","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Archiving the Trans Formations Project","type":"text","version":1}],"tag":"h3","direction":null,"format":"","indent":0,"version":1},{"type":"heading","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Preserving Movement Infrastructure","type":"text","version":1}],"tag":"h4","direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"The Trans Formations Project (TFP) was a trans-led, grassroots, volunteer-driven 501(c)(4) organization that emerged in response to the escalating anti-trans legislative crisis in the United States. From its founding in 2021, Trans Formations built critical digital infrastructure to track, document, and resist coordinated legislative attacks on transgender communities nationwide.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"While engaging in their legislative tracking work, the Trans Formations Project built and maintained a comprehensive database of anti-trans and trans-affirming legislation introduced at the state and federal levels across all 50 states, alongside a parallel dataset containing contact information for elected officials and their voting records on trans-related bills in committee and on the floor. This work transformed fragmented legislative information into a usable, action-oriented resource for organizers, advocates, and constituents.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"DQC was conceived by our cofounders shortly after their volunteer tenure with the TFP abruptly came to an end with the closing of the organization due to increasingly hostile political environment in September 2025. As such, DQC’s archival project exists to preserve, steward, and extend this infrastructure of resistance by archiving the Trans Formations’ Project’s work. We are safeguarding a uniquely valuable record of trans-targeted policy activity and the community labor that made it legible.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"We understand archiving not as passive preservation, but as an active political practice. Maintaining this dataset ensures that trans communities and allied organizations retain access to the tools needed to hold power accountable, respond rapidly to legislative threats, and build informed strategies for collective liberation. In doing so, we honor Trans Formations’ legacy while reinforcing the digital infrastructure necessary for ongoing queer resistance and self-determination.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Data","type":"text","version":1}],"tag":"h3","direction":null,"format":"","indent":0,"version":1},{"type":"quote","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Under Construction","type":"text","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"heading","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Newsletters","type":"text","version":1}],"tag":"h3","direction":null,"format":"","indent":0,"version":1},{"type":"quote","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Under Construction","type":"text","version":1}],"direction":null,"format":"","indent":0,"version":1}],"direction":null,"format":"","indent":0,"version":1}}$dqc$::jsonb, (now() at time zone 'utc'), $dqc${"root":{"type":"root","children":[{"type":"heading","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Archiving the Trans Formations Project","type":"text","version":1}],"tag":"h3","direction":null,"format":"","indent":0,"version":1},{"type":"heading","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Preserving Movement Infrastructure","type":"text","version":1}],"tag":"h4","direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"The Trans Formations Project (TFP) was a trans-led, grassroots, volunteer-driven 501(c)(4) organization that emerged in response to the escalating anti-trans legislative crisis in the United States. From its founding in 2021, Trans Formations built critical digital infrastructure to track, document, and resist coordinated legislative attacks on transgender communities nationwide.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"While engaging in their legislative tracking work, the Trans Formations Project built and maintained a comprehensive database of anti-trans and trans-affirming legislation introduced at the state and federal levels across all 50 states, alongside a parallel dataset containing contact information for elected officials and their voting records on trans-related bills in committee and on the floor. This work transformed fragmented legislative information into a usable, action-oriented resource for organizers, advocates, and constituents.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"DQC was conceived by our cofounders shortly after their volunteer tenure with the TFP abruptly came to an end with the closing of the organization due to increasingly hostile political environment in September 2025. As such, DQC’s archival project exists to preserve, steward, and extend this infrastructure of resistance by archiving the Trans Formations’ Project’s work. We are safeguarding a uniquely valuable record of trans-targeted policy activity and the community labor that made it legible.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"We understand archiving not as passive preservation, but as an active political practice. Maintaining this dataset ensures that trans communities and allied organizations retain access to the tools needed to hold power accountable, respond rapidly to legislative threats, and build informed strategies for collective liberation. In doing so, we honor Trans Formations’ legacy while reinforcing the digital infrastructure necessary for ongoing queer resistance and self-determination.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Data","type":"text","version":1}],"tag":"h3","direction":null,"format":"","indent":0,"version":1},{"type":"quote","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Under Construction","type":"text","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"heading","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Newsletters","type":"text","version":1}],"tag":"h3","direction":null,"format":"","indent":0,"version":1},{"type":"quote","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Under Construction","type":"text","version":1}],"direction":null,"format":"","indent":0,"version":1}],"direction":null,"format":"","indent":0,"version":1}}$dqc$::jsonb, (now() at time zone 'utc')
) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "team_member" ("id", "name", "pronouns", "draft_content", "draft_updated_at", "published_content", "published_at", "sort_order") VALUES (
  '01a2054f-34ba-722e-bf3d-426a4b27981e', $dqc$Devin Sharpe$dqc$, $dqc$he/him$dqc$, $dqc${"root":{"type":"root","children":[{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Devin Sharpe is the co-founder of DQC, where he leads the development and advancement of the collective’s projects and initiatives. Devin’s formative years were spent in Detroit and the surrounding areas, while his adolescence was nurtured in the South, namely the Atlanta metro area. His life experience has been defined by his position at the intersections of different identities. Growing up as a mixed-race, bisexual man in a semi-nomadic, heavily spiritual household gave him an optimistic belief that one’s true self will take root despite societal and/or personal pressures to repress it.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Professionally, Devin works as a frontend-focused software engineer, and has assisted teams in creating products or experiences that delight everyday users and consumers while refusing to neglect those who rely on accessibility assists. His current post at ","type":"text","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Strata Company","type":"text","version":1}],"rel":"noreferrer","target":null,"title":null,"url":"https://gostrata.com","direction":null,"format":"","indent":0,"type":"link","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", based in Pennsylvania, has him leading the frontend development of a new product that connects digitally-minded marketing professionals with a revitalized mail outreach channel. Prior to Strata, Devin has served at a number of other companies, such as the Washington Post, where he assisted with experimental products and initiatives.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Prior to starting DQC, Devin volunteered with queer advocacy organizations in his free time, mostly with the ","type":"text","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Trans Formations Project","type":"text","version":1}],"rel":"noreferrer","target":null,"title":null,"url":"https://transformationsproject.org","direction":null,"format":"","indent":0,"type":"link","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":". At TFP, he served on the Widget Development team and helped use US legislative bill data collected by the organization to create compelling web applications to assist queer people looking to track dangerous, anti-trans legislation or how their representatives were voting on their behalf.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"By starting DQC and working with its members, Devin hopes to continue to uplift the 2SLGBTQIA+ community by creating digital spaces where queer safety is prioritized, identities are accepted, and queer advocacy can happen.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}$dqc$::jsonb, (now() at time zone 'utc'), $dqc${"root":{"type":"root","children":[{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Devin Sharpe is the co-founder of DQC, where he leads the development and advancement of the collective’s projects and initiatives. Devin’s formative years were spent in Detroit and the surrounding areas, while his adolescence was nurtured in the South, namely the Atlanta metro area. His life experience has been defined by his position at the intersections of different identities. Growing up as a mixed-race, bisexual man in a semi-nomadic, heavily spiritual household gave him an optimistic belief that one’s true self will take root despite societal and/or personal pressures to repress it.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Professionally, Devin works as a frontend-focused software engineer, and has assisted teams in creating products or experiences that delight everyday users and consumers while refusing to neglect those who rely on accessibility assists. His current post at ","type":"text","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Strata Company","type":"text","version":1}],"rel":"noreferrer","target":null,"title":null,"url":"https://gostrata.com","direction":null,"format":"","indent":0,"type":"link","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", based in Pennsylvania, has him leading the frontend development of a new product that connects digitally-minded marketing professionals with a revitalized mail outreach channel. Prior to Strata, Devin has served at a number of other companies, such as the Washington Post, where he assisted with experimental products and initiatives.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Prior to starting DQC, Devin volunteered with queer advocacy organizations in his free time, mostly with the ","type":"text","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Trans Formations Project","type":"text","version":1}],"rel":"noreferrer","target":null,"title":null,"url":"https://transformationsproject.org","direction":null,"format":"","indent":0,"type":"link","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":". At TFP, he served on the Widget Development team and helped use US legislative bill data collected by the organization to create compelling web applications to assist queer people looking to track dangerous, anti-trans legislation or how their representatives were voting on their behalf.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"By starting DQC and working with its members, Devin hopes to continue to uplift the 2SLGBTQIA+ community by creating digital spaces where queer safety is prioritized, identities are accepted, and queer advocacy can happen.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}$dqc$::jsonb, (now() at time zone 'utc'), 0
) ON CONFLICT DO NOTHING;
