INSERT INTO "team_member" ("id", "name", "pronouns", "draft_content", "draft_updated_at", "published_content", "published_at", "sort_order") VALUES (
  '01a2054f-34ba-722e-bf3d-479f63372c0a', $dqc$Laith Stevenson$dqc$, $dqc$she/they$dqc$, $dqc${"root":{"type":"root","children":[{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Laith Stevenson is the co-founder of ","type":"text","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"DQC(3)","type":"text","version":1}],"rel":"noreferrer","target":null,"title":null,"url":"https://dqc3.org","direction":null,"format":"","indent":0,"type":"link","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", where she works at the intersection of queer justice, technology, and civic infrastructure. As an out and proud black trans woman from the rural South, Laith’s work is shaped by lived experience navigating systems of surveillance, exclusion, and legislative violence—experiences that ground DQC3’s commitment to building community-controlled digital tools for advancing liberation movements.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Currently, Laith is a graduate student at the ","type":"text","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"University of Pennsylvania’s School of Social Policy & Practice (SP2)","type":"text","version":1}],"rel":"noreferrer","target":null,"title":null,"url":"https://sp2.upenn.edu/","direction":null,"format":"","indent":0,"type":"link","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", where she studies social policy with a focus on data ethics, technology governance, and the political economy of automation. She is pursuing a Certificate in Applied Data Ethics, Law, and the Social Good and conducts research on the artificial intelligence, digital equity, and the the socio-technical governance implications of emerging technologies.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Laith is also a Policy Advocacy Intern with ","type":"text","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Public Knowledge","type":"text","version":1}],"rel":"noreferrer","target":null,"title":null,"url":"https://publicknowledge.org/","direction":null,"format":"","indent":0,"type":"link","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", supporting federal advocacy on open internet policy, communications competition, and balanced intellectual property frameworks Her professional background spans litigation support, social science research, nonprofit development, and digital communications—experiences that inform her interdisciplinary approach to policy analysis and technical capacity building.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"She has been deeply involved in trans-led legislative resistance efforts, including volunteering with the ","type":"text","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Trans Formations Project","type":"text","version":1}],"rel":"noreferrer","target":null,"title":null,"url":"https://transformationsproject.org","direction":null,"format":"","indent":0,"type":"link","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", where she contributed bill summaries to a comprehensive database tracking anti-trans and trans-affirming legislation nationwide through. She also serves on the board of the ","type":"text","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Center for Abolition Research, Policy, and Education (CARPE)","type":"text","version":1}],"rel":"noreferrer","target":null,"title":null,"url":"https://carpeatlanta.com/","direction":null,"format":"","indent":0,"type":"link","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", supporting, research, governance and strategy for Black trans advocacy.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Through DQC3, Laith advances a model of queer tech work rooted in intersectionality, accessibility, and collective power. She understands digital infrastructure as a site of political struggle and believes that building ethical, justice-driven technology is essential to sustaining social movements, protecting marginalized communities, and imagining liberated futures.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}$dqc$::jsonb, (now() at time zone 'utc'), $dqc${"root":{"type":"root","children":[{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Laith Stevenson is the co-founder of ","type":"text","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"DQC(3)","type":"text","version":1}],"rel":"noreferrer","target":null,"title":null,"url":"https://dqc3.org","direction":null,"format":"","indent":0,"type":"link","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", where she works at the intersection of queer justice, technology, and civic infrastructure. As an out and proud black trans woman from the rural South, Laith’s work is shaped by lived experience navigating systems of surveillance, exclusion, and legislative violence—experiences that ground DQC3’s commitment to building community-controlled digital tools for advancing liberation movements.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Currently, Laith is a graduate student at the ","type":"text","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"University of Pennsylvania’s School of Social Policy & Practice (SP2)","type":"text","version":1}],"rel":"noreferrer","target":null,"title":null,"url":"https://sp2.upenn.edu/","direction":null,"format":"","indent":0,"type":"link","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", where she studies social policy with a focus on data ethics, technology governance, and the political economy of automation. She is pursuing a Certificate in Applied Data Ethics, Law, and the Social Good and conducts research on the artificial intelligence, digital equity, and the the socio-technical governance implications of emerging technologies.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Laith is also a Policy Advocacy Intern with ","type":"text","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Public Knowledge","type":"text","version":1}],"rel":"noreferrer","target":null,"title":null,"url":"https://publicknowledge.org/","direction":null,"format":"","indent":0,"type":"link","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", supporting federal advocacy on open internet policy, communications competition, and balanced intellectual property frameworks Her professional background spans litigation support, social science research, nonprofit development, and digital communications—experiences that inform her interdisciplinary approach to policy analysis and technical capacity building.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"She has been deeply involved in trans-led legislative resistance efforts, including volunteering with the ","type":"text","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Trans Formations Project","type":"text","version":1}],"rel":"noreferrer","target":null,"title":null,"url":"https://transformationsproject.org","direction":null,"format":"","indent":0,"type":"link","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", where she contributed bill summaries to a comprehensive database tracking anti-trans and trans-affirming legislation nationwide through. She also serves on the board of the ","type":"text","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Center for Abolition Research, Policy, and Education (CARPE)","type":"text","version":1}],"rel":"noreferrer","target":null,"title":null,"url":"https://carpeatlanta.com/","direction":null,"format":"","indent":0,"type":"link","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", supporting, research, governance and strategy for Black trans advocacy.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Through DQC3, Laith advances a model of queer tech work rooted in intersectionality, accessibility, and collective power. She understands digital infrastructure as a site of political struggle and believes that building ethical, justice-driven technology is essential to sustaining social movements, protecting marginalized communities, and imagining liberated futures.","type":"text","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}$dqc$::jsonb, (now() at time zone 'utc'), 1
) ON CONFLICT DO NOTHING;
